python3 -c "
import json
for run in ['run-bare','run-rules','run-checker']:
    print(f'=== {run} ===')
    tools=[]; texts=[]
    session_id=None; result=None
    for line in open(f'evidence/{run}.jsonl'):
        d=json.loads(line)
        if d.get('type')=='system' and d.get('subtype')=='init':
            session_id=d.get('session_id','?')[:8]
        if d.get('type')=='assistant':
            for c in d['message']['content']:
                if c['type']=='tool_use':
                    tools.append((c['name'], (c['input'].get('file_path') or c['input'].get('command') or c['input'].get('pattern') or '')[:60]))
                elif c['type']=='text' and c['text'].strip():
                    texts.append(c['text'].strip()[:200])
        if d.get('type')=='result':
            result=(d.get('duration_ms',0)/1000, d.get('num_turns'), d.get('total_cost_usd'), d.get('subtype'))
    print(f'session {session_id} · {result[3]} · turns={result[1]} · {result[0]:.1f}s · \${result[2]:.4f}')
    for t in tools:
        print(f'  TOOL {t[0]:<8} {t[1]}')
    for t in texts:
        print(f'  TEXT {t}')
    print()
"

