    ap.add_argument("--strict-coverage", action="store_true",
                    help="promote the FC-4 coverage advisory to a blocking defect")
    a = ap.parse_args()
    blockers, advisories, st = check(a.reel_dir, strict_coverage=a.strict_coverage)
